test:
s = OrderedIntStream([-3, 0, 0, 5])
assert iter(s) is s
assert s.next() == -3
assert next(s) == 0
assert list(s) == [0, 5]
for _ in range(2):
    try:
        s.next()
    except StopIteration:
        pass
    else:
        raise AssertionError('An exhausted stream must stay exhausted')

s = OrderedIntStream([])
assert list(s) == []
try:
    next(s)
except StopIteration:
    pass
else:
    raise AssertionError('Empty input must raise StopIteration')

s = MergeStream([OrderedIntStream(v) for v in [[-2, 2, 2], [], [-2, 1, 2, 7], [0, 3]]])
assert list(s) == [-2, -2, 0, 1, 2, 2, 2, 3, 7]
for _ in range(2):
    try:
        next(s)
    except StopIteration:
        pass
    else:
        raise AssertionError('An exhausted merge must stay exhausted')
